#include<bits/stdc++.h>
#define int long long
using namespace std;
int a[111111],b[111111];
signed main(){
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	int n;
	cin>>n;
	for(int i=1;i<=n;i++){
		cin>>a[i];
		b[i]=1;
	}
	if(a[1]>a[n]){
		b[1]=max(b[1],b[n]+1);
	}
	if(a[1]>a[2]){
		b[1]=max(b[1],b[2]+1);
	}
	for(int i=2;i<n;i++){
		if(a[i]>a[i-1]){
			b[i]=max(b[i],b[i-1]+1);
		}
		if(a[i]>a[i+1]){
			b[i]=max(b[i],b[i+1]+1);
		}
	}
	if(a[n]>a[1]){
		b[n]=max(b[n],b[1]+1);
	}
	if(a[n]>a[n-1]){
		b[n]=max(b[n],b[n-1]+1);
	}
	int ans=0;
	for(int i=1;i<=n;i++){
		ans+=b[i];
	}
	cout<<ans;
    return 0;
}
